import pandas as pd
import numpy as np

# Load the data
no2_data = pd.read_csv('chunks_csv/getisord/getisord_no2_Q4_2022.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Replace missing values with the mean of the dataset
no2_data['avg_no2_value'] = no2_data['avg_no2_value'].fillna(no2_data['avg_no2_value'].mean())

# Define the neighborhood relationships
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the combined NO2 values
combined_no2 = {}
for index, row in no2_data.iterrows():
    if not np.isnan(row['avg_no2_value']):
        combined_no2[row['borough']] = row['avg_no2_value']
        for neighbor in neighborhoods[row['borough']]:
            if not np.isnan(no2_data[no2_data['borough'] == neighbor]['avg_no2_value'].values[0]):
                combined_no2[row['borough']] += no2_data[no2_data['borough'] == neighbor]['avg_no2_value'].values[0]

# Apply the Getis-Ord Gi* method
citywide_mean = no2_data['avg_no2_value'].mean()
citywide_std = no2_data['avg_no2_value'].std()
gi_values = {}
for borough, value in combined_no2.items():
    gi_values[borough] = (value - citywide_mean) / citywide_std

# Identify statistically significant hot and cold spots
hot_spots = []
cold_spots = []
for borough, value in gi_values.items():
    if np.abs(value) > 1.96:
        if value > 0:
            hot_spots.append(borough)
        else:
            cold_spots.append(borough)

# Report the results
data_points_used = len(gi_values)
results = [f"{borough} (HOT, Gi*={value:.4f})" for borough, value in gi_values.items() if np.abs(value) > 1.96] + [f"{borough} (COLD, Gi*={value:.4f})" for borough, value in gi_values.items() if np.abs(value) > 1.96]
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {', '.join(results)}")
